sources.CapacityGuard.ts:
export class CapacityGuard {
  check(code: string): boolean {
    return code === 'buffer-full'
  }
}

sources.BufferNote.ts:
export class BufferNote {
  check(code: string): boolean {
    return code === 'buffer'
  }
}

sources.EmptyGuard.ts:
export class EmptyGuard {
  check(code: string): boolean {
    return code === 'buffer-empty'
  }
}
